import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.z3u3TMv0.js";const g=JSON.parse('{"title":"OpenRouter","description":"OpenRouter Free-Modelle — Free Models Collection, :free Text/Vision, Key & Limits, Eintrag in MiniTavern.","frontmatter":{"title":"OpenRouter","description":"OpenRouter Free-Modelle — Free Models Collection, :free Text/Vision, Key & Limits, Eintrag in MiniTavern.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"OpenRouter · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenRouter Free-Modelle — Free Models Collection, :free Text/Vision, Key & Limits, Eintrag in MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/free-cloud/openrouter"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/free-cloud/openrouter"}]]},"headers":[],"relativePath":"de/free-cloud/openrouter.md","filePath":"de/free-cloud/openrouter.md","lastUpdated":1787224147000}'),d={name:"de/free-cloud/openrouter.md"};function i(n,e,l,s,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h1><p>Globales Aggregator-Gateway: ein API Key für viele Modelle. Teilweise <strong>Free-Pool</strong> (IDs oft mit <code>:free</code> oder offiziell Free) — persönlich, Open-Source-Vergleich, seltenes Roleplay. Offizielle Collection: <a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a>; Drittliste: <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a> (nicht offiziell — Konsole gilt).</p><blockquote><p>Free-Listen und RPM/Tageslimits ändern sich. <strong><a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models</a> und Account gelten</strong>.</p></blockquote><h2 id="website-einstiege" tabindex="-1">Website &amp; Einstiege <a class="header-anchor" href="#website-einstiege" aria-label="Permalink to &quot;Website &amp; Einstiege&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ressource</th><th>Adresse</th></tr></thead><tbody><tr><td>Website</td><td><a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a></td></tr><tr><td>API Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>Free Models</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">openrouter.ai/collections/free-models</a></td></tr><tr><td>Modellplatz (Free)</td><td><a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models?q=free</a></td></tr><tr><td>Community (Dritt)</td><td><a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr><tr><td>API Base URL</td><td><code>https://openrouter.ai/api/v1</code> (bei App <strong>OpenRouter</strong> meist ohne Handfüllung)</td></tr></tbody></table><h2 id="free-holen" tabindex="-1">Free holen <a class="header-anchor" href="#free-holen" aria-label="Permalink to &quot;Free holen&quot;">​</a></h2><ol><li><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a> registrieren und Key (<strong>meist ohne Kreditkarte</strong>).</li><li>In <a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> oder Platz <strong>Model ID</strong> kopieren (<code>:free</code> beachten).</li><li>MiniTavern Plattform <strong>OpenRouter</strong>, Key, diese ID.</li></ol><table tabindex="0"><thead><tr><th>Punkt</th><th>Hinweis</th></tr></thead><tbody><tr><td>Free</td><td>ID mit <code>:free</code> oder Collection <code>$0</code>; Auto-Route <code>openrouter/free</code></td></tr><tr><td>Limits</td><td>oft ca. <strong>20 RPM / ~50/Tag</strong>; einmalig ca. <strong>$10+</strong> kann Free-Tageslimit auf ~<strong>1000/Tag</strong> heben (offizielle Regeln)</td></tr><tr><td>Kreditkarte</td><td>Free meist ohne; Aufladen für Limits oder Paid</td></tr><tr><td>Privacy</td><td>manches Free-Upstream darf Prompts nutzen; Privacy in OpenRouter-Settings. Poolside Laguna Free laut Doku ggf. Training</td></tr></tbody></table><h2 id="modellliste" tabindex="-1">Modellliste <a class="header-anchor" href="#modellliste" aria-label="Permalink to &quot;Modellliste&quot;">​</a></h2><p>Häufige <strong>Text/Vision</strong>-IDs (ca. 2026-08); <strong>Website gilt</strong>. IDs <strong>case-sensitive</strong>, <code>:free</code> nicht weglassen (außer Eintrag ohne Suffix).</p><h3 id="text-·-auto-route" tabindex="-1">Text · Auto-Route <a class="header-anchor" href="#text-·-auto-route" aria-label="Permalink to &quot;Text · Auto-Route&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Modell-ID</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>openrouter/free</code></td><td>wählt verfügbares Free-Modell; schnellster Einstieg, Qualität variabel</td></tr></tbody></table><h3 id="text-·-allgemeiner-dialog" tabindex="-1">Text · Allgemeiner Dialog <a class="header-anchor" href="#text-·-allgemeiner-dialog" aria-label="Permalink to &quot;Text · Allgemeiner Dialog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Modell-ID</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>meta-llama/llama-3.3-70b-instruct:free</code></td><td>allgemein, mehrsprachig</td></tr><tr><td><code>meta-llama/llama-3.2-3b-instruct:free</code></td><td>leicht</td></tr><tr><td><code>openai/gpt-oss-20b:free</code> / <code>openai/gpt-oss-120b:free</code></td><td>OpenAI Open-Weight MoE</td></tr><tr><td><code>google/gemma-3-27b-it:free</code> / <code>google/gemma-3-12b-it:free</code> / <code>google/gemma-3-4b-it:free</code></td><td>Gemma 3</td></tr><tr><td><code>google/gemma-4-31b-it:free</code> / <code>google/gemma-4-26b-a4b-it:free</code></td><td>Gemma 4 (teils Vision)</td></tr><tr><td><code>google/gemma-3n-e4b-it:free</code> / <code>google/gemma-3n-e2b-it:free</code></td><td>On-Device-leicht</td></tr><tr><td><code>qwen/qwen3-next-80b-a3b-instruct:free</code></td><td>Qwen3 Chat</td></tr><tr><td><code>z-ai/glm-4.5-air:free</code></td><td>GLM leicht, chinesischfreundlich</td></tr><tr><td><code>minimax/minimax-m2.5:free</code></td><td>MiniMax</td></tr><tr><td><code>nousresearch/hermes-3-llama-3.1-405b:free</code></td><td>Hermes 3</td></tr><tr><td><code>arcee-ai/trinity-large-preview:free</code></td><td>Arcee Trinity Large Preview</td></tr><tr><td><code>openrouter/elephant-alpha</code></td><td>gehostetes Textmodell (wenn Free markiert)</td></tr><tr><td><code>cognitivecomputations/dolphin-mistral-24b-venice-edition:free</code></td><td>Venice Uncensored Variante (Inhalt selbst einschätzen)</td></tr></tbody></table><h3 id="text-·-reasoning-agent-coding" tabindex="-1">Text · Reasoning / Agent / Coding <a class="header-anchor" href="#text-·-reasoning-agent-coding" aria-label="Permalink to &quot;Text · Reasoning / Agent / Coding&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Modell-ID</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>qwen/qwen3-coder:free</code></td><td>Qwen3 Coder</td></tr><tr><td><code>nvidia/nemotron-3-ultra:free</code> (oder aktuelle Collection-ID)</td><td>Nemotron 3 Ultra, langer Agent-Kontext</td></tr><tr><td><code>nvidia/nemotron-3.5-lightning:free</code></td><td>hoher Agent-Durchsatz</td></tr><tr><td><code>nvidia/nemotron-3-super-120b-a12b:free</code></td><td>Nemotron 3 Super</td></tr><tr><td><code>nvidia/nemotron-3-nano-30b-a3b:free</code> / <code>nvidia/nemotron-nano-9b-v2:free</code></td><td>Nano</td></tr><tr><td><code>poolside/laguna-s-2.1:free</code> / <code>poolside/laguna-xs-2.1:free</code> (Platz-ID)</td><td>Poolside Coding Agent; Free ggf. Training</td></tr><tr><td><code>cohere/north-mini-code:free</code> (Platz)</td><td>Cohere North Coding</td></tr><tr><td><code>liquid/lfm-2.5-1.2b-instruct:free</code> / <code>liquid/lfm-2.5-1.2b-thinking:free</code></td><td>Liquid leicht</td></tr><tr><td><code>dots-studio/dots3-note-preview:free</code> (Platz)</td><td>Dots3-Note Preview</td></tr></tbody></table><p>Collection-Reihenfolge ändert sich; Coding auch unter <a href="https://openrouter.ai/collections/coding" target="_blank" rel="noreferrer">Coding</a> Free filtern.</p><h3 id="text-·-vision-multimodaler-input" tabindex="-1">Text · Vision (multimodaler Input) <a class="header-anchor" href="#text-·-vision-multimodaler-input" aria-label="Permalink to &quot;Text · Vision (multimodaler Input)&quot;">​</a></h3><p>Hauptmodell mit Vision für App-Bilderkennung / Multimodal:</p><table tabindex="0"><thead><tr><th>Modell-ID</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>google/gemma-3-27b-it:free</code> und Gemma 3/4</td><td>Text + Bild</td></tr><tr><td><code>nvidia/nemotron-nano-12b-v2-vl:free</code></td><td>Vision / Dokumente</td></tr><tr><td><code>nvidia/nemotron-3-nano-omni:free</code> (Platz)</td><td>multimodale Perception</td></tr><tr><td><code>meta-llama/llama-guard-4-12b:free</code></td><td>Safety-Klassifikation, meist kein Chat-Hauptmodell</td></tr></tbody></table><h3 id="bild-video" tabindex="-1">Bild / Video <a class="header-anchor" href="#bild-video" aria-label="Permalink to &quot;Bild / Video&quot;">​</a></h3><ul><li><strong>Bild</strong>: OpenRouter <a href="https://openrouter.ai/collections/image-models" target="_blank" rel="noreferrer">Image Models</a>; Free laut Preis. MiniTavern Bildverbindung <strong>OpenRouter</strong> möglich.</li><li><strong>Video</strong>: <a href="https://openrouter.ai/collections/video-models" target="_blank" rel="noreferrer">Video Models</a>; App <strong>ohne Video-Einstieg</strong>.</li><li>Lyria usw. in Drittlisten eher Musik — nicht als Chatmodell.</li></ul><h2 id="eintrag-in-minitavern" tabindex="-1">Eintrag in MiniTavern <a class="header-anchor" href="#eintrag-in-minitavern" aria-label="Permalink to &quot;Eintrag in MiniTavern&quot;">​</a></h2><p>Allgemein: <a href="/ultra_guides/de/manual/model-link">Modellverbindung</a>.</p><h3 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h3><p>Pfad: <strong>Einstellungen → Modelle → Modellverbindung → Neu</strong></p><ol><li>Plattform <strong>OpenRouter</strong> (Preset Base URL)</li><li>API Key</li><li>z. B. <code>meta-llama/llama-3.3-70b-instruct:free</code> oder <code>openrouter/free</code></li><li><strong>Testen</strong> → Standard</li></ol><p>Oder <strong>Custom (OpenAI)</strong> mit Base URL <code>https://openrouter.ai/api/v1</code>; Preset bevorzugen.</p><h3 id="bild" tabindex="-1">Bild <a class="header-anchor" href="#bild" aria-label="Permalink to &quot;Bild&quot;">​</a></h3><p>Pfad: <strong>Einstellungen → Bildgenerierung → Bildverbindung</strong> → <strong>OpenRouter</strong>, ID mit Image und Free (oder akzeptable Kosten). Stabileres Free-Bild: <a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a>, <a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a>.</p><h3 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td><code>HTTP 429</code> / <code>Provider returned error</code></td><td>Free-Pool voll/limitiert: anderes <code>:free</code>, später, oder <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a></td></tr><tr><td>Zugang aus CN fehlgeschlagen</td><td>ggf. Proxy; oder Direkt-Anbieter / <a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a></td></tr><tr><td>404 / unavailable</td><td><code>:free</code> offline: ID neu aus Collection</td></tr></tbody></table><p>Mehr: <a href="/ultra_guides/de/manual/errors">Fehlercodes</a>.</p><h2 id="verwandte-kapitel" tabindex="-1">Verwandte Kapitel <a class="header-anchor" href="#verwandte-kapitel" aria-label="Permalink to &quot;Verwandte Kapitel&quot;">​</a></h2><ul><li><a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud Übersicht</a></li><li><a href="/ultra_guides/de/free-cloud/freellm">FreeLLM-Verzeichnis</a></li><li><a href="/ultra_guides/de/free-cloud/aihubmix">AIHubMix</a> — gesponserte <code>*-free</code></li><li><a href="/ultra_guides/de/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/de/free-cloud/opencode-zen">OpenCode Zen</a></li><li><a href="/ultra_guides/de/manual/model-link">Modellverbindung</a></li><li><a href="/ultra_guides/de/free-cloud/#kostenlose-bildgenerierung">Kostenlose Bildgenerierung</a></li></ul>',35)])])}const f=t(d,[["render",i]]);export{g as __pageData,f as default};
